"""Tests for code_skool.data_structures module."""

import pytest
from code_skool.data_structures import (
    word_frequency,
    find_common,
    group_by,
    sort_by,
    demo,
)


class TestWordFrequency:
    """Tests for the word frequency counter."""

    def test_basic_counting(self):
        result = word_frequency("the cat and the dog")
        assert result["the"] == 2
        assert result["cat"] == 1
        assert result["and"] == 1
        assert result["dog"] == 1

    def test_case_insensitive(self):
        result = word_frequency("Hello hello HELLO")
        assert result["hello"] == 3

    def test_empty_string(self):
        result = word_frequency("")
        assert result == {}

    def test_single_word(self):
        result = word_frequency("python")
        assert result == {"python": 1}

    def test_punctuation_stripped(self):
        result = word_frequency("hello, world! hello.")
        assert result["hello"] == 2
        assert result["world"] == 1

    def test_non_string_raises(self):
        with pytest.raises(TypeError):
            word_frequency(42)

    def test_repeated_words(self):
        result = word_frequency("a a a b b c")
        assert result["a"] == 3
        assert result["b"] == 2
        assert result["c"] == 1


class TestFindCommon:
    """Tests for finding common elements between lists."""

    def test_basic_common(self):
        result = find_common([1, 2, 3, 4], [3, 4, 5, 6])
        assert result == [3, 4]

    def test_no_common(self):
        result = find_common([1, 2], [3, 4])
        assert result == []

    def test_all_common(self):
        result = find_common([1, 2, 3], [1, 2, 3])
        assert result == [1, 2, 3]

    def test_empty_lists(self):
        assert find_common([], []) == []
        assert find_common([1, 2], []) == []
        assert find_common([], [1, 2]) == []

    def test_strings(self):
        result = find_common(["apple", "banana"], ["banana", "cherry"])
        assert result == ["banana"]

    def test_result_is_sorted(self):
        result = find_common([5, 3, 1], [1, 3, 5])
        assert result == [1, 3, 5]

    def test_duplicates_handled(self):
        """Duplicates in input should not cause duplicate output."""
        result = find_common([1, 1, 2, 2], [2, 2, 3, 3])
        assert result == [2]

    def test_non_list_raises(self):
        with pytest.raises(TypeError):
            find_common("abc", [1, 2])


class TestGroupBy:
    """Tests for grouping dictionaries by key."""

    def test_basic_grouping(self):
        items = [
            {"name": "Alice", "dept": "Sales"},
            {"name": "Bob",   "dept": "IT"},
            {"name": "Carol", "dept": "Sales"},
        ]
        result = group_by(items, "dept")
        assert len(result["Sales"]) == 2
        assert len(result["IT"]) == 1

    def test_single_group(self):
        items = [{"x": 1, "g": "a"}, {"x": 2, "g": "a"}]
        result = group_by(items, "g")
        assert list(result.keys()) == ["a"]
        assert len(result["a"]) == 2

    def test_missing_key(self):
        """Items without the key go to 'unknown' group."""
        items = [{"name": "Alice"}, {"name": "Bob", "dept": "IT"}]
        result = group_by(items, "dept")
        assert "unknown" in result
        assert len(result["unknown"]) == 1

    def test_empty_list(self):
        result = group_by([], "key")
        assert result == {}

    def test_non_dict_item_raises(self):
        with pytest.raises(TypeError):
            group_by(["not", "dicts"], "key")

    def test_non_list_raises(self):
        with pytest.raises(TypeError):
            group_by("not a list", "key")


class TestSortBy:
    """Tests for sorting dictionaries by key."""

    def test_sort_ascending(self):
        items = [{"name": "Charlie"}, {"name": "Alice"}, {"name": "Bob"}]
        result = sort_by(items, "name")
        assert [r["name"] for r in result] == ["Alice", "Bob", "Charlie"]

    def test_sort_descending(self):
        items = [{"val": 1}, {"val": 3}, {"val": 2}]
        result = sort_by(items, "val", reverse=True)
        assert [r["val"] for r in result] == [3, 2, 1]

    def test_does_not_modify_original(self):
        items = [{"v": 3}, {"v": 1}, {"v": 2}]
        original_order = [d["v"] for d in items]
        sort_by(items, "v")
        assert [d["v"] for d in items] == original_order

    def test_empty_list(self):
        assert sort_by([], "key") == []

    def test_non_list_raises(self):
        with pytest.raises(TypeError):
            sort_by("not a list", "key")


class TestDemo:
    """Tests for the combined demo() function."""

    def test_runs_without_error(self, capsys):
        demo()
        output = capsys.readouterr().out
        assert "Word Frequency" in output
        assert "Common Elements" in output
        assert "Group By" in output
        assert "Sort By" in output

