class TestRockPaperScissors:
    """Tests for rock-paper-scissors."""

    def test_player_wins(self):
        assert rock_paper_scissors("rock", "scissors") == "win"
        assert rock_paper_scissors("paper", "rock") == "win"
        assert rock_paper_scissors("scissors", "paper") == "win"

    def test_player_loses(self):
        assert rock_paper_scissors("rock", "paper") == "lose"
        assert rock_paper_scissors("paper", "scissors") == "lose"
        assert rock_paper_scissors("scissors", "rock") == "lose"

    def test_tie(self):
        assert rock_paper_scissors("rock", "rock") == "tie"
        assert rock_paper_scissors("paper", "paper") == "tie"

    def test_case_insensitive(self):
        assert rock_paper_scissors("ROCK", "scissors") == "win"
        assert rock_paper_scissors("Rock", "Paper") == "lose"

    def test_invalid_choice(self):
        with pytest.raises(ValueError):
            rock_paper_scissors("fire", "rock")


class TestCheckPasswordStrength:
    """Tests for the password strength checker."""

    def test_weak_too_short(self):
        assert check_password_strength("abc") == "weak"
        assert check_password_strength("1234567") == "weak"

    def test_weak_no_digit(self):
        """8+ chars but no digit -> weak."""
        assert check_password_strength("abcdefgh") == "weak"

    def test_medium_with_digit(self):
        assert check_password_strength("abcdef1g") == "medium"

    def test_strong_with_digit_and_special(self):
        assert check_password_strength("P@ssw0rd!") == "strong"

    def test_invalid_type(self):
        with pytest.raises(TypeError):
            check_password_strength(12345678)


class TestDemo:
    """Tests for the combined demo() function."""

    def test_runs_without_error(self, capsys):
        demo()
        output = capsys.readouterr().out
        assert "Grade Classifier" in output
        assert "Leap Year" in output
        assert "Rock Paper Scissors" in output
        assert "Password Strength" in output

